/bin/bash -lc "cat > output.html <<'EOF'
<"'!doctype html>
<html lang="th">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>พร้อมพบ — จองห้องประชุม</title>
<style>
:root{--ink:#203d37;--muted:#74817c;--green:#245e4d;--lime:#e5edbc;--bg:#f6f7f3;--line:#e3e7e0;--white:#fff;--red:#a83e39}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Tahoma,Arial,sans-serif;font-size:14px}button,input,select{font:inherit}button,a,input,select{ -webkit-tap-highlight-color:transparent}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.45}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #96b76a;outline-offset:3px}button{border:0}aside{position:fixed;inset:0 auto 0 0;width:230px;background:#fff;border-right:1px solid var(--line);padding:34px 22px;display:flex;flex-direction:column;z-index:2}.brand{display:flex;align-items:center;gap:11px;font-size:24px;font-weight:bold;letter-spacing:-1px}.brandmark{width:36px;height:36px;border-radius:11px;background:var(--green);display:grid;place-items:center;color:#e4edb7;font-size:24px}.brand small{display:block;font-size:9px;letter-spacing:2.5px;color:var(--muted);margin-top:4px}.workspace{margin:38px 0 23px;font-size:11px;letter-spacing:1.5px;color:var(--muted)}nav{display:grid;gap:9px}.nav{background:transparent;color:var(--muted);padding:14px 15px;border-radius:10px;display:flex;gap:13px;text-align:left;align-items:center}.nav.active{background:#edf2e8;color:var(--green);font-weight:bold}.nav svg{width:19px;height:19px}.side-note{margin-top:auto;background:#f6f7f1;border:1px solid var(--line);border-radius:14px;padding:17px;font-size:12px;line-height:1.8}.side-note strong{display:block;margin-bottom:6px}.side-bottom{padding:24px 0 0;color:var(--muted);font-size:11px}main{margin-left:230px;padding:0 42px 36px;max-width:1680px}.topbar{height:89px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}.profile{display:flex;gap:12px;align-items:center}.avatar{display:grid;place-items:center;background:#e9eddf;width:35px;height:35px;border-radius:50%;font-weight:bold;color:var(--green)}.hero{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:35px 0 25px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--green);font-weight:bold}h1{font-size:32px;letter-spacing:-1px;margin:9px 0 10px}p{line-height:1.7}.subtitle{color:var(--muted);margin:0;font-size:13px}.primary{background:var(--green);color:white;border-radius:9px;padding:12px 18px;font-weight:bold}.primary:hover{background:#184635}.secondary{background:white;color:var(--ink);border:1px solid var(--line);border-radius:9px;padding:11px 15px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:26px}.stat{padding:20px 23px;border:1px solid var(--line);border-radius:13px;background:white;display:flex;align-items:center;justify-content:space-between}.stat.highlight{background:#eaf0dc;border-color:#e1e8d3}.stat-label{color:#65716b;font-size:12px}.stat-value{font-size:29px;font-weight:bold;margin-top:8px}.stat-icon{font-size:23px;width:44px;height:44px;display:grid;place-items:center;background:#f3f5ed;border-radius:12px;color:#5f795a}.toolbar{display:flex;gap:13px;align-items:end;background:white;border:1px solid var(--line);border-radius:12px;padding:16px;margin-bottom:28px}.field{display:grid;gap:7px;min-width:0}.field label{font-size:11px;color:#66766c}.field input,.field select{width:100%;border:1px solid #dfe5dc;background:#fff;border-radius:8px;padding:10px;color:var(--ink);min-height:42px}.grow{flex:1}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:17px;gap:12px}h2{font-size:18px;margin:0}.count{font-size:12px;font-weight:normal;color:var(--muted);margin-left:8px}.toggle{display:flex;background:#e9ece4;padding:4px;border-radius:9px;gap:2px}.toggle button{background:transparent;padding:8px 12px;border-radius:6px;color:#67716b;font-size:12px}.toggle button.active{background:white;color:var(--ink);box-shadow:0 1px 3px #142e1810}.room-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.room-card{background:white;border:1px solid var(--line);border-radius:14px;overflow:hidden}.room-art{height:154px;position:relative;overflow:hidden;background:var(--tone)}.room-art svg{width:100%;height:100%;display:block}.room-no{position:absolute;left:16px;top:14px;color:#37564a;font-size:10px;letter-spacing:1.5px;background:#ffffffab;padding:6px 8px;border-radius:5px}.room-body{padding:20px}.room-title{display:flex;justify-content:space-between;align-items:center;gap:10px}.room-title h3{font-size:20px;margin:0}.badge{font-size:10px;border-radius:20px;padding:6px 9px;background:#edf4e6;color:#476b39;white-space:nowrap}.badge.cancelled{background:#f9e9e6;color:var(--red)}.badge.completed{background:#eee;color:#666}.meta{font-size:12px;color:var(--muted);margin:9px 0 15px}.amenities{display:flex;gap:6px;flex-wrap:wrap}.tag{border:1px solid #e8ebe5;border-radius:5px;padding:5px 8px;color:#62756a;font-size:10px}.room-footer{border-top:1px solid #eef0eb;padding-top:14px;margin-top:18px;display:flex;justify-content:space-between;align-items:center;gap:8px}.room-footer span{font-size:11px;color:var(--muted)}.room-footer button{padding:9px 14px;font-size:12px}.foot{display:flex;justify-content:space-between;gap:12px;color:#879087;font-size:10px;margin-top:28px}.empty{text-align:center;border:1px dashed #cad5c5;border-radius:12px;padding:45px 20px;background:white;grid-column:1/-1}.empty h3{margin-top:0}.empty p{color:var(--muted)}[hidden]{display:none!important}.schedule{background:white;border:1px solid var(--line);border-radius:13px;padding:22px;overflow:auto}.timeline-row{display:grid;grid-template-columns:100px repeat(24, minmax(24px,1fr));gap:2px;min-width:760px;align-items:center;margin:13px 0}.timeline-row .hour{font-size:10px;color:var(--muted);grid-column:span 2}.slot{height:35px;border-radius:4px;background:#e9f1dd;color:#345837;padding:0;font-size:10px}.slot:hover{background:#cfdfa9}.slot.busy{background:#e5d8c4;color:#7e613d}.slot.past{background:#eceee9}.legend{display:flex;gap:17px;color:var(--muted);font-size:11px;flex-wrap:wrap;margin:12px 0}.dot{display:inline-block;width:9px;height:9px;border-radius:3px;margin-right:5px;background:#e9f1dd}.dot.busy{background:#e5d8c4}.dot.past{background:#eceee9}.booking-list{display:grid;gap:13px}.booking{background:white;border:1px solid var(--line);border-radius:12px;padding:20px;display:flex;align-items:center;gap:18px}.date-tile{background:#f0f3e8;border-radius:10px;min-width:58px;text-align:center;padding:10px;font-size:11px}.date-tile b{display:block;font-size:23px;margin-top:4px}.booking-content{flex:1;min-width:0}.booking h3{font-size:15px;margin:0 0 8px;overflow-wrap:anywhere}.booking p{font-size:12px;color:var(--muted);margin:0}.booking-actions{display:flex;gap:12px;align-items:center}.danger{background:white;color:var(--red);border:1px solid #ecd8d3;border-radius:8px;padding:8px 11px;font-size:12px}dialog{border:1px solid var(--line);border-radius:18px;padding:0;color:var(--ink);width:510px;max-width:calc(100% - 28px);max-height:90vh;box-shadow:0 24px 100px #17372733}dialog::backdrop{background:#17302760;backdrop-filter:blur(3px)}.dialog-head{padding:24px 25px 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.close{background:#f2f4ed;border-radius:50%;height:30px;width:30px;font-size:20px;color:#5c6b5f}.dialog-body{padding:23px 25px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.form-grid .full{grid-column:1/-1}.form-grid label{font-size:12px}.dialog-footer{display:flex;gap:10px;justify-content:flex-end;margin-top:22px}.hint{font-size:11px;color:var(--muted);line-height:1.8;margin:12px 0 0}.error{color:var(--red);font-size:12px;line-height:1.7;margin-top:14px}.availability{background:#f3f6ed;border-radius:8px;padding:11px;margin-bottom:18px;font-size:12px;line-height:1.8}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#234e40;color:white;padding:14px 22px;border-radius:10px;box-shadow:0 8px 25px #183d3022;z-index:10;max-width:90%;font-size:13px}.storage-warning{background:#fff2db;padding:12px;border-radius:9px;font-size:12px;margin-top:16px}.sample{font-size:10px;color:#957943;margin-left:7px}@media(min-width:1450px){.room-art{height:185px}}@media(max-width:1000px){aside{width:190px;padding:28px 16px}main{margin-left:190px;padding:0 24px 30px}.toolbar{flex-wrap:wrap}.toolbar .grow{flex-basis:100%}h1{font-size:27px}.stat{padding:17px}.stat-icon{display:none}.booking{flex-wrap:wrap}}@media(max-width:700px){aside{position:static;width:auto;padding:18px 20px;border-right:0;border-bottom:1px solid var(--line)}.brand{font-size:22px}.workspace,.side-note,.side-bottom{display:none}nav{display:flex;margin-top:20px;gap:7px}.nav{flex:1;padding:11px;font-size:12px;justify-content:center}main{margin:0;padding:0 18px 25px}.topbar{height:57px;font-size:10px}.profile{gap:6px}.avatar{height:28px;width:28px}.hero{margin:25px 0 22px;align-items:start}.hero .primary{font-size:11px;padding:11px;white-space:nowrap;margin-top:26px}h1{font-size:24px}.subtitle{font-size:11px}.eyebrow{font-size:9px}.summary{gap:8px;margin-bottom:20px}.stat{padding:13px 10px}.stat-label{font-size:10px}.stat-value{font-size:24px}.toolbar{padding:12px;gap:10px;margin-bottom:23px}.toolbar .field{flex:1}.toolbar .grow{flex-basis:100%}.room-grid{grid-template-columns:1fr}.room-art{height:172px}.section-head{align-items:center}h2{font-size:16px}.toggle button{padding:7px 9px}.foot{flex-direction:column;gap:6px}.booking{padding:15px;gap:12px}.booking-actions{width:100%;justify-content:flex-end}.dialog-body{padding:20px}.dialog-head{padding:20px}.room-title h3{font-size:19px}}@media(prefers-reduced-motion:no-preference){button{transition:background .15s,box-shadow .15s}.room-card{animation:appear .25s ease-out}@keyframes appear{from{opacity:.5;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}}
</style>
</head>
<body>
<aside><div class="brand"><span class="brandmark">◧</span><div>พร้อมพบ<small>ROOM TO CONNECT</small></div></div><div class="workspace">YOUR WORKSPACE</div><nav aria-label="เมนูหลัก"><button class="nav active" id="roomsNav" aria-current="page"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>ค้นหาห้องประชุม</button><button class="nav" id="bookingsNav"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v5m8-5v5M4 11h16m-12 4h8m-8 3h5"/></svg>การจองของฉัน</button></nav><div class="side-note"><strong>พื้นที่ดี ๆ สำหรับทุกไอเดีย</strong>เลือกห้องที่ใช่ แล้วให้การประชุม<br>ครั้งต่อไปเริ่มต้นได้อย่างราบรื่น<br><br>เวลาให้บริการ 08:00–20:00</div><div class="side-bottom">● &nbsp; โหมดสาธิต · ใช้งานออฟไลน์</div></aside>
<main><header class="topbar"><span>เวิร์กสเปซ &nbsp; / &nbsp; ห้องประชุม</span><div class="profile"><span>ผู้ใช้งานทดลอง</span><span class="avatar">P</span></div></header><div class="storage-warning" id="storageWarning" hidden>เบราว์เซอร์ไม่อนุญาตให้เก็บข้อมูล การจองจะอยู่เฉพาะระหว่างเปิดหน้านี้</div><section class="hero"><div><span class="eyebrow">MAKE SPACE FOR GREAT IDEAS</span><h1 id="pageTitle">พื้นที่สำหรับไอเดียดี ๆ</h1><p class="subtitle" id="pageSubtitle">ค้นหาห้องที่เหมาะกับทีม แล้วนัดพบกันได้เลย</p></div><button class="primary" id="newBooking">＋ จองห้องประชุม</button></section><div class="summary"><div class="stat"><div><div class="stat-label">ห้องประชุมทั้งหมด</div><div class="stat-value">4 <span style="font-size:11px;font-weight:normal">ห้อง</span></div></div><span class="stat-icon" aria-hidden="true">▦</span></div><div class="stat highlight"><div><div class="stat-label">มีช่วงว่างในวันที่เลือก</div><div class="stat-value" id="availableCount">—</div></div><span class="stat-icon" aria-hidden="true">◷</span></div><div class="stat"><div><div class="stat-label">การจองที่กำลังจะมาถึง</div><div class="stat-value" id="bookingCount">—</div></div><span class="stat-icon" aria-hidden="true">▤</span></div></div>
<section id="roomsSection"><div class="toolbar"><div class="field"><label for="filterDate">วันที่ใช้ห้อง</label><input type="date" id="filterDate" required></div><div class="field"><label for="capacity">จำนวนผู้เข้าร่วม</label><select id="capacity"><option value="0">ทุกขนาดห้อง</option><option value="4">4 คนขึ้นไป</option><option value="8">8 คนขึ้นไป</option><option value="12">12 คนขึ้นไป</option><option value="16">16 คนขึ้นไป</option></select></div><div class="field grow"><label for="search">ค้นหาห้องหรืออุปกรณ์</label><input id="search" type="search" placeholder="เช่น ห้องต้นไทร, โปรเจกเตอร์"></div></div><div class="section-head"><h2>ห้องประชุม<span id="resultCount" class="count"></span></h2><div class="toggle" aria-label="รูปแบบการแสดงผล"><button id="gridView" class="active" aria-pressed="true">▦ &nbsp; ห้องทั้งหมด</button><button id="scheduleView" aria-pressed="false">◷ &nbsp; ตารางเวลา</button></div></div><div id="rooms" class="room-grid"></div><div id="schedule" class="schedule" hidden></div></section>
<section id="bookingsSection" hidden><div class="section-head"><h2>การจองของฉัน</h2><div class="field"><label for="statusFilter" class="hint">กรองสถานะ</label><select id="statusFilter"><option value="all">ทุกสถานะ</option><option value="confirmed">ยืนยันแล้ว</option><option value="cancelled">ยกเลิกแล้ว</option><option value="completed">เสร็จสิ้น</option></select></div></div><p class="hint" style="margin-bottom:18px">รายการทุกวันที่ของผู้ใช้ทดลอง รวมข้อมูลตัวอย่างที่ระบุไว้</p><div id="bookings" class="booking-list"></div></section><footer class="foot"><span>พร้อมพบ — ให้ทุกการพบกันมีความหมาย</span><span>ระบบจำลอง · เวลาเครื่องของคุณ · ข้อมูลเก็บเฉพาะเบราว์เซอร์นี้</span></footer></main>
<dialog id="bookingDialog" aria-labelledby="dialogTitle"><div class="dialog-head"><h2 id="dialogTitle">จองห้องประชุม</h2><button type="button" class="close" id="closeBooking" aria-label="ปิดหน้าจอง">×</button></div><form id="bookingForm" class="dialog-body"><div class="availability" id="roomAvailability"></div><div class="form-grid"><div class="field full"><label for="bookRoom">ห้องประชุม</label><select id="bookRoom" required></select></div><div class="field full"><label for="title">หัวข้อการประชุม</label><input id="title" required maxlength="80" placeholder="เช่น วางแผนโปรเจกต์ประจำสัปดาห์"></div><div class="field"><label for="bookDate">วันที่</label><input type="date" id="bookDate" required></div><div class="field"><label for="attendees">ผู้เข้าร่วม (คน)</label><input type="number" id="attendees" min="1" max="16" value="2" required step="1"></div><div class="field"><label for="startTime">เวลาเริ่ม</label><select id="startTime" required></select></div><div class="field"><label for="endTime">เวลาสิ้นสุด</label><select id="endTime" required></select></div></div><p class="hint">เปิด 08:00–20:00 · จองเป็นช่วงละ 30 นาที<br>ตรวจเวลาว่างและจำนวนผู้เข้าร่วมก่อนยืนยันทุกครั้ง</p><div class="error" id="formError" role="alert" hidden></div><div class="dialog-footer"><button type="button" class="secondary" id="backBooking">กลับ</button><button type="submit" class="primary">ยืนยันการจอง</button></div></form></dialog>
<dialog id="cancelDialog" aria-labelledby="cancelTitle"><div class="dialog-head"><h2 id="cancelTitle">ยกเลิกการจองนี้?</h2><button class="close" id="closeCancel" aria-label="ปิดหน้ายกเลิก">×</button></div><div class="dialog-body"><p id="cancelDetail"></p><p class="hint">เมื่อยกเลิก ช่วงเวลานี้จะกลับมาว่าง และรายการจะอยู่ในประวัติการจอง</p><div class="dialog-footer"><button class="secondary" id="keepBooking">เก็บการจองไว้</button><button class="primary" id="confirmCancel">ยืนยันยกเลิก</button></div></div></dialog><div id="toast" class="toast" role="status" hidden></div>
<script>
'"'use strict';
const "'$=id=>document.getElementById(id), rooms=[{id:'"'r1',name:'ห้องต้นไทร',en:'BANYAN',floor:'ชั้น 2',cap:8,tools:['จอภาพ 55 นิ้ว','ไวท์บอร์ด','วิดีโอคอล'],tone:'#e5e9dc',accent:'#637761'},{id:'r2',name:'ห้องมะกอก',en:'OLIVE',floor:'ชั้น 2',cap:4,tools:['จอภาพ 43 นิ้ว','ไวท์บอร์ด'],tone:'#ece5d9',accent:'#a38b6c'},{id:'r3',name:'ห้องสน',en:'PINE',floor:'ชั้น 3',cap:12,tools:['โปรเจกเตอร์','ไวท์บอร์ด','วิดีโอคอล'],tone:'#dce8e7',accent:'#648584'},{id:'r4',name:'ห้องจามจุรี',en:'RAIN TREE',floor:'ชั้น 3',cap:16,tools:['โปรเจกเตอร์','ไมโครโฟน','วิดีโอคอล'],tone:'#e6e1d8',accent:'#807561'}];
const key='promphop.bookings.v1';
function localDate(d=new Date()){return "'`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'"'0')}-"'${String(d.getDate()).padStart(2,'"'0')}"'`}
const today=localDate(), initial=new Date();if(initial.getHours()>=20)initial.setDate(initial.getDate()+1);const initialDate=localDate(initial);
const time=n=>`${String(Math.floor(n/60)).padStart(2,'"'0')}:"'${String(n%60).padStart(2,'"'0')}"'`;
const minutes=s=>Number(s.slice(0,2))*60+Number(s.slice(3));
const dateTime=(d,t)=>new Date(`${d}T${t}:00`);
const escape=s=>String(s).replace(/[&<>"'"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'});
let data=[],storageOK=true,view='grid',cancelId=null,toastTimer;
function validRecord(b){return b&&typeof b.id==='string'&&rooms.some(r=>r.id===b.room)&&typeof b.title==='string'&&b.title.trim().length>0&&b.title.length<=80&&/"'^'"\\d{4}-\\d{2}-\\d{2}"'$/.test(b.date)&&Number.isFinite(dateTime(b.date,'"'12:00').getTime())&&/"'^'"\\d{2}:(00|30)"'$/.test(b.start)&&/''^'"\\d{2}:(00|30)"'$/.test(b.end)&&minutes(b.start)>=480&&minutes(b.end)<=1200&&minutes(b.end)>minutes(b.start)&&Number.isInteger(b.attendees)&&b.attendees>=1&&b.attendees<=rooms.find(r=>r.id===b.room).cap&&['"'confirmed','cancelled'].includes(b.status)}
try{const raw=localStorage.getItem(key);if(raw"'!==null){const parsed=JSON.parse(raw);if(!Array.isArray(parsed)||!parsed.every(validRecord))throw Error('"'invalid');data=parsed;}else{data=[{id:'sample-1',room:'r2',title:'ทีมดีไซน์ · Weekly sync',date:initialDate,start:'10:00',end:'11:00',attendees:4,status:'confirmed',sample:true},{id:'sample-2',room:'r4',title:'วางแผนงานประจำเดือน',date:initialDate,start:'13:00',end:'14:00',attendees:10,status:'confirmed',sample:true}];localStorage.setItem(key,JSON.stringify(data));}}catch(e){storageOK=false;"'$('"'storageWarning').hidden=false;}
function save(){try{if("'!storageOK)return;localStorage.setItem(key,JSON.stringify(data));}catch(e){storageOK=false;$('"'storageWarning').hidden=false;}}
