try{const raw=localStorage.getItem(key);if(raw"'!==null){const parsed=JSON.parse(raw);if(!Array.isArray(parsed)||!parsed.every(validRecord))throw Error('"'invalid');data=parsed;}else{data=[{id:'sample-1',room:'r2',title:'ทีมดีไซน์ · Weekly sync',date:initialDate,start:'10:00',end:'11:00',attendees:4,status:'confirmed',sample:true},{id:'sample-2',room:'r4',title:'วางแผนงานประจำเดือน',date:initialDate,start:'13:00',end:'14:00',attendees:10,status:'confirmed',sample:true}];localStorage.setItem(key,JSON.stringify(data));}}catch(e){storageOK=false;"'$('"'storageWarning').hidden=false;}
